\begin{ex}%[6H5N1]
\immini[thm]{
Tìm trục đối xứng của hình ảnh sau
}{
\begin{tikzpicture}
    % Vẽ nền cờ đỏ
    \fill[red] (0,0) rectangle (6,4);

    % Tâm của ngôi sao
    \coordinate (O) at (3,2);

    % Bán kính và các điểm cho ngôi sao vàng
    \def\R{1} % Bán kính lớn của ngôi sao
    \def\r{0.4} % Bán kính nhỏ của ngôi sao

    % Các điểm của ngôi sao (theo chiều kim đồng hồ)
    \foreach \i in {18,90,162,234,306} {
        \coordinate (\i) at ($(O)+(\i:\R)$); % Điểm trên bán kính lớn
    }

    % Các điểm trong của ngôi sao (theo chiều kim đồng hồ)
    \foreach \i in {54,126,198,270,342} {
        \coordinate (\i) at ($(O)+(\i:\r)$); % Điểm trên bán kính nhỏ
    }

    % Vẽ ngôi sao vàng
    \fill[yellow] (18) -- (54) -- (90) -- (126) -- (162) -- (198) -- (234) -- (270) -- (306) -- (342) -- cycle;

\end{tikzpicture}
}
